package com.kennedy.wallet.config;
import org.springframework.boot.context.properties.ConfigurationProperties; import java.time.Duration; import java.util.List;
@ConfigurationProperties("wallet") public class WalletProperties {
 private final Jwt jwt=new Jwt(); private final Cors cors=new Cors(); private final Transfer transfer=new Transfer(); private final B2c b2c=new B2c(); private final Fraud fraud=new Fraud(); public Jwt getJwt(){return jwt;} public Cors getCors(){return cors;} public Transfer getTransfer(){return transfer;} public B2c getB2c(){return b2c;} public Fraud getFraud(){return fraud;}
 public static class Jwt {private String secret;private String issuer="wallet-service",audience="wallet-api";private Duration accessTtl=Duration.ofMinutes(15);public String getSecret(){return secret;}public void setSecret(String x){secret=x;}public String getIssuer(){return issuer;}public void setIssuer(String x){issuer=x;}public String getAudience(){return audience;}public void setAudience(String x){audience=x;}public Duration getAccessTtl(){return accessTtl;}public void setAccessTtl(Duration x){accessTtl=x;}}
 public static class Cors {private List<String> allowedOrigins=List.of();public List<String> getAllowedOrigins(){return allowedOrigins;}public void setAllowedOrigins(List<String> x){allowedOrigins=x;}}
 public static class Transfer {private long minimumAmountMinor=100,maximumAmountMinor=150000000,dailyLimitMinor=50000000;private String currency="KES";private List<FeeTier> fees=new java.util.ArrayList<>(List.of(new FeeTier(100000,100,0),new FeeTier(Long.MAX_VALUE,200,0)));public long getMinimumAmountMinor(){return minimumAmountMinor;}public void setMinimumAmountMinor(long x){minimumAmountMinor=x;}public long getMaximumAmountMinor(){return maximumAmountMinor;}public void setMaximumAmountMinor(long x){maximumAmountMinor=x;}public long getDailyLimitMinor(){return dailyLimitMinor;}public void setDailyLimitMinor(long x){dailyLimitMinor=x;}public String getCurrency(){return currency;}public void setCurrency(String x){currency=x;}public List<FeeTier> getFees(){return fees;}public void setFees(List<FeeTier> x){fees=x;}}
 public static class FeeTier {private long upToMinor,flatFeeMinor;private int basisPoints;public FeeTier(){}public FeeTier(long upTo,long flat,int bps){upToMinor=upTo;flatFeeMinor=flat;basisPoints=bps;}public long getUpToMinor(){return upToMinor;}public void setUpToMinor(long x){upToMinor=x;}public long getFlatFeeMinor(){return flatFeeMinor;}public void setFlatFeeMinor(long x){flatFeeMinor=x;}public int getBasisPoints(){return basisPoints;}public void setBasisPoints(int x){basisPoints=x;}}
 public static class B2c {private boolean mockSuccess=true;private long mockDelayMillis=1500;public boolean isMockSuccess(){return mockSuccess;}public void setMockSuccess(boolean x){mockSuccess=x;}public long getMockDelayMillis(){return mockDelayMillis;}public void setMockDelayMillis(long x){mockDelayMillis=x;}}
 public static class Fraud {private int transfersPerMinute=10,newRecipientsWindowMinutes=10,newRecipientsLimit=5,repeatedFailedLoginCount=5;private long singleAmountFlagMinor=10000000;public int getTransfersPerMinute(){return transfersPerMinute;}public void setTransfersPerMinute(int x){transfersPerMinute=x;}public int getNewRecipientsWindowMinutes(){return newRecipientsWindowMinutes;}public void setNewRecipientsWindowMinutes(int x){newRecipientsWindowMinutes=x;}public int getNewRecipientsLimit(){return newRecipientsLimit;}public void setNewRecipientsLimit(int x){newRecipientsLimit=x;}public int getRepeatedFailedLoginCount(){return repeatedFailedLoginCount;}public void setRepeatedFailedLoginCount(int x){repeatedFailedLoginCount=x;}public long getSingleAmountFlagMinor(){return singleAmountFlagMinor;}public void setSingleAmountFlagMinor(long x){singleAmountFlagMinor=x;}}
}
